turn_private.assistant_event_erase_autho.prosrc:
declare f privacy_private.linked_delete_fences_v1%rowtype;
begin
 if exists(select 1 from turn_data_private.transaction_proofs_v1 p
  join turn_data_private.operations_v1 o on o.request_id=p.request_id and o.owner_id=p.owner_id
  where p.transaction_id=pg_current_xact_id() and p.owner_id=e.owner_id
   and p.source_digest=o.source_digest and p.graph=o.graph and p.expires_at=o.expires_at
   and p.expires_at>floor(extract(epoch from clock_timestamp())*1000)::bigint
   and (p.graph->'turnIds' ? e.turn_id::text or p.graph->'artifactIds' ? e.artifact_id::text)) then return true;end if;
 if conversation_data_private.proof_v1(e.owner_id,'turnIds',e.turn_id)
  or conversation_data_private.proof_v1(e.owner_id,'taskIds',e.task_id)
  or conversation_data_private.proof_v1(e.owner_id,'conversationIds',e.conversation_id)
  or (e.artifact_id is not null and conversation_data_private.proof_v1(e.owner_id,'artifactIds',e.artifact_id))
  or (e.artifact_id is not null and result_data_private.proof_v1('artifactIds',e.artifact_id)) then return true;end if;
 for f in select * from privacy_private.linked_delete_fences_v1 where owner_id=e.owner_id
  and ((entity_kind='turn' and entity_id=e.turn_id) or (entity_kind='task' and entity_id=e.task_id)
   or (entity_kind='artifact' and entity_id=e.artifact_id)) loop
  if privacy_private.linked_delete_erase_authority_v1(f.request_id,f.entity_kind,f.entity_id) then return true;end if;
 end loop;
 return false;
end

turn_private.retire_assistant_event_v1(u.prosrc:
declare e turn_private.assistant_events_v1%rowtype;h turn_private.assistant_event_heads_v1%rowtype;
begin
 -- No source-row locks acquired here; the original eraser already owns them.
 -- Head precedes mutable delivery row, matching original producer allocation.
 select * into h from turn_private.assistant_event_heads_v1 where conversation_id=p_conversation for update;
 if not found then return;end if;
 select * into e from turn_private.assistant_events_v1 where conversation_id=p_conversation and sequence=p_sequence for update;
 if not found or e.source_kind='retired' then return;end if;
 if not turn_private.assistant_event_erase_authorized_v1(e) then raise exception 'ASSISTANT_EVENT_ERASE_AUTHORITY';end if;
 if h.last_sequence=999999999999999 then raise exception 'ASSISTANT_EVENT_SEQUENCE_LIMIT';end if;
 update turn_private.assistant_events_v1 set source_kind='retired',source_key='ordinal:'||sequence::text,
  task_id=null,turn_id=null,event_type='source_retired',status=null,tool=null,action_state=null,
  artifact_id=null,revision=null,retired_sequence=sequence where conversation_id=p_conversation and sequence=p_sequence;
 insert into turn_private.assistant_events_v1(owner_id,conversation_id,sequence,source_kind,source_key,event_type,retired_sequence)
  values(e.owner_id,p_conversation,h.last_sequence+1,'retired','retirement:'||p_sequence::text,'source_retired',p_sequence);
 update turn_private.assistant_event_heads_v1 set last_sequence=h.last_sequence+1 where conversation_id=p_conversation;
end

turn_private.assistant_delivery_source_v.prosrc:
declare rows_n jsonb;n integer;
begin
 if not turn_data_private.runtime_supported_v1() then raise exception 'ASSISTANT_EVENT_SCHEMA_UNSUPPORTED';end if;
 select coalesce(jsonb_agg(jsonb_build_object('conversationId',conversation_id,'sequence',sequence,
  'digest',result_data_private.digest_v1(to_jsonb(e)::text)) order by conversation_id,sequence),'[]'::jsonb),count(*)
 into rows_n,n from (
  select * from turn_private.assistant_events_v1 x where owner_id=p_owner and source_kind<>'retired'
   and (coalesce(p_graph->'turnIds','[]'::jsonb) ? x.turn_id::text
    or coalesce(p_graph->'artifactIds','[]'::jsonb) ? x.artifact_id::text)
   order by conversation_id,sequence limit 4101
 ) e;
 if n>4100 or octet_length(rows_n::text)>65536 then raise exception 'ASSISTANT_EVENT_SCOPE_TOO_LARGE';end if;
 return jsonb_build_object('rows',rows_n);
end

turn_private.lock_assistant_delivery_v1(.prosrc:
declare x record;
begin
 -- Original caller has already locked all original selected parent/source rows.
 -- No subsequent original Task/Turn/source lock is acquired by this helper.
 for x in select distinct (value->>'conversationId')::uuid id from jsonb_array_elements(p_witness->'rows') order by id loop
  perform 1 from turn_private.assistant_event_heads_v1 where conversation_id=x.id and owner_id=p_owner for update nowait;
  if not found then raise exception 'ASSISTANT_EVENT_SOURCE_CHANGED';end if;
 end loop;
 if turn_private.assistant_delivery_source_v1(p_owner,p_graph) is distinct from p_witness then raise exception 'ASSISTANT_EVENT_SOURCE_CHANGED';end if;
 perform 1 from turn_private.assistant_events_v1 e where owner_id=p_owner and exists(select 1 from jsonb_array_elements(p_witness->'rows') witness_row
  where (witness_row->>'conversationId')::uuid=e.conversation_id and (witness_row->>'sequence')::bigint=e.sequence)
  order by conversation_id,sequence for update nowait;
end

turn_private.retire_assistant_delivery_v.prosrc:
declare x jsonb;
begin
 perform turn_private.lock_assistant_delivery_v1(p_owner,p_graph,p_witness);
 for x in select value from jsonb_array_elements(p_witness->'rows') order by (value->>'conversationId')::uuid,(value->>'sequence')::bigint loop
  perform turn_private.retire_assistant_event_v1((x->>'conversationId')::uuid,(x->>'sequence')::bigint);
 end loop;
end

conversation_data_private.source_v1(uuid.prosrc:
declare closure_n jsonb;g jsonb;spec record;actual_n jsonb;key_n jsonb;ref record;qualified_n boolean;
 rows_n jsonb:='[]';reverse_n jsonb:='[]';authorities_n jsonb:='[]';witness_n jsonb;conflicts_n text[]:=array[]::text[];
 erase_n jsonb:=conversation_data_private.zero_counts_v1('erase');redact_n jsonb:=conversation_data_private.zero_counts_v1('redact');
 retain_n jsonb:=conversation_data_private.zero_counts_v1('retain');refs_n jsonb;trips_n uuid[]:=array[]::uuid[];memory_n uuid[]:=array[]::uuid[];
 executions uuid[]:=array[]::uuid[];turns uuid[];tasks uuid[];messages uuid[];goals uuid[];artifacts uuid[];threads uuid[];
 n integer;total_n integer:=0;reverse_total integer:=0;other_n jsonb;fingerprint_n jsonb;assistant_delivery_n jsonb;relation_n text;extra_n uuid[];
begin
 -- Root ownership/policy precede source feedback, even on a capacity blocker.
 if root_kind_n='conversation' then
  select jsonb_build_array(jsonb_build_object('policyId',policy_id,'consentId',consent_id)) into authorities_n
   from turn_private.assistant_conversations where id=root_id_n and owner_id=u;
  if not found then raise exception 'CONVERSATION_SOURCE_UNAVAILABLE';end if;
  perform conversation_data_private.authorities_current_v1(u,authorities_n);
 elsif root_kind_n='thread' then
  perform 1 from public.chat_threads where id=root_id_n and owner_id=u;if not found then raise exception 'CONVERSATION_SOURCE_UNAVAILABLE';end if;
 else raise exception 'INVALID_INPUT';end if;
 closure_n:=conversation_data_private.closure_v1(u,root_kind_n,root_id_n);g:=closure_n->'graph';
 select coalesce(array_agg(value#>>'{}'),array[]::text[]) into conflicts_n from jsonb_array_elements(closure_n->'conflicts');
 if not conversation_data_private.schema_supported_v1() then conflicts_n:=conflicts_n||array['SOURCE_UNSUPPORTED'];end if;
 if conflicts_n @> array['SCOPE_TOO_LARGE'] then
  return jsonb_build_object('graph',g,'eraseCounts',erase_n,'redactCounts',redact_n,'retainCounts',retain_n,'sourceAuthorities',authorities_n,
   'retainedReferences','{"tripIds":[],"memoryIds":[]}'::jsonb,'conflicts',conversation_data_private.conflicts_v1(conflicts_n),'rows','[]'::jsonb,
   'sourceDigest',conversation_data_private.digest_v1(jsonb_build_array(g,conflicts_n,authorities_n)::text));
 end if;
 turns:=privacy_private.linked_delete_array_v1(g->'turnIds');tasks:=privacy_private.linked_delete_array_v1(g->'taskIds');
 messages:=privacy_private.linked_delete_array_v1(g->'messageIds');goals:=privacy_private.linked_delete_array_v1(g->'goalIds');
 artifacts:=privacy_private.linked_delete_array_v1(g->'artifactIds');threads:=privacy_private.linked_delete_array_v1(g->'threadIds');
